import { format, fromUnixTime } from 'date-fns';
import { c } from 'ttag';

import { ButtonLike } from '@proton/atoms';
import SettingsLink from '@proton/components/components/link/SettingsLink';
import type { ModalProps } from '@proton/components/components/modalTwo/Modal';
import Prompt from '@proton/components/components/prompt/Prompt';
import { PLANS } from '@proton/payments';
import { dateLocale } from '@proton/shared/lib/i18n';

import { useSubscription } from '@proton/account/subscription/hooks';
import useCancellationTelemetry, { REACTIVATE_SOURCE } from './useCancellationTelemetry';

interface Props extends ModalProps {
    plan: PLANS;
    planName: string;
}

const CancelRedirectionModal = ({ planName, plan, ...props }: Props) => {
    const { sendResubscribeModalResubcribeReport, sendResubscribeModalCloseReport } = useCancellationTelemetry();
    const [subscription] = useSubscription();
    const subscriptionEndDate = format(fromUnixTime(subscription?.PeriodEnd ?? 0), 'PPP', { locale: dateLocale });
    const boldedDate = <strong>{subscriptionEndDate}</strong>;

    const ResubscribeButton = () => {
        if (plan === PLANS.VISIONARY) {
            return null;
        }

        return (
            <ButtonLike
                as={SettingsLink}
                onClick={() => {
                    sendResubscribeModalResubcribeReport();
                }}
                fullWidth
                path={`/dashboard?source=${REACTIVATE_SOURCE.cancellationFlow}#your-subscriptions`}
                data-testid="cancellation-reminder-resubscribe-button"
            >{c('Subscription reminder').t`Reactivate`}</ButtonLike>
        );
    };

    const continueText = c('Subscription reminder')
        .jt`You can continue to enjoy all the benefits of your current plan until ${boldedDate}.`;

    const reactivateText = c('Subscription reminder').t`Reactivate to restore access to ${planName} features.`;

    return (
        <Prompt
            {...props}
            title={c('Subscription reminder').t`Subscription canceled`}
            data-testid="cancellation-reminder-redirection"
            buttons={[
                <ButtonLike
                    as={SettingsLink}
                    onClick={() => {
                        sendResubscribeModalCloseReport();
                    }}
                    color="norm"
                    data-testid="cancellation-reminder-dashboard-button"
                    path="/dashboard"
                >{c('Subscription reminder').t`Got it`}</ButtonLike>,
                <ResubscribeButton />,
            ]}
        >
            <p>{continueText}</p>
            <p>{reactivateText}</p>
        </Prompt>
    );
};

export default CancelRedirectionModal;
import { render } from '@testing-library/react';
import { addMonths, format, getUnixTime } from 'date-fns';

import { subscriptionMock, upcomingSubscriptionMock } from '@proton/testing/data';

import { CancelSubscriptionModal } from './CancelSubscriptionModal';

jest.mock('@proton/components/components/portal/Portal');

const onResolve = jest.fn();
const onReject = jest.fn();

it('should render', () => {
    const { container } = render(
        <CancelSubscriptionModal subscription={subscriptionMock} onResolve={onResolve} onReject={onReject} open />
    );
    expect(container).not.toBeEmptyDOMElement();
});

it('should return status kept when clicking on keep subscription', () => {
    const { getByTestId } = render(
        <CancelSubscriptionModal subscription={subscriptionMock} onResolve={onResolve} onReject={onReject} open />
    );
    getByTestId('keepSubscription').click();
    expect(onResolve).toHaveBeenCalledWith({ status: 'kept' });
});

it('should return status cancelled when clicking on cancel subscription', () => {
    const { getByTestId } = render(
        <CancelSubscriptionModal subscription={subscriptionMock} onResolve={onResolve} onReject={onReject} open />
    );
    getByTestId('cancelSubscription').click();
    expect(onResolve).toHaveBeenCalledWith({ status: 'cancelled' });
});

it('should display end date of the current subscription', () => {
    // We ensure to have a date in the future to avoid formatting errors
    const futureDate = addMonths(new Date(), 2);
    const adaptedSubscription = {
        ...subscriptionMock,
        PeriodEnd: getUnixTime(futureDate),
    };

    const { container } = render(
        <CancelSubscriptionModal subscription={adaptedSubscription} onResolve={onResolve} onReject={onReject} open />
    );

    const expectedDate = format(futureDate, 'PP');
    expect(container).toHaveTextContent(`expires on ${expectedDate}`);
});

it('should display the end date of the upcoming subscription if it exists', () => {
    const { container } = render(
        <CancelSubscriptionModal
            subscription={{ ...subscriptionMock, UpcomingSubscription: upcomingSubscriptionMock }}
            onResolve={onResolve}
            onReject={onReject}
            open
        />
    );

    expect(container).toHaveTextContent('expires on Jun 5, 2026');
});

import { PLANS } from '@proton/payments';
import type { APP_NAMES } from '@proton/shared/lib/constants';
import { getPlan } from '@proton/shared/lib/helpers/subscription';
import type { SubscriptionModel, UserModel } from '@proton/shared/lib/interfaces';

import { getBundleConfig } from './config/bundle';
import { getBundleProConfig } from './config/bundlePro';
import { getDrivePlusConfig } from './config/drivePlus';
import { getDuoConfig } from './config/duo';
import { getFamilyConfig } from './config/family';
import { getMailBusinessConfig } from './config/mailBusiness';
import { getMailEssentialConfig } from './config/mailEssential';
import { getMailPlusConfig } from './config/mailPlus';
import { getVisionaryConfig } from './config/visionary';
import type { PlanConfig } from './interface';

export const getReminderPageConfig = ({
    app,
    subscription,
    user,
}: {
    app?: APP_NAMES;
    subscription?: SubscriptionModel;
    user: UserModel;
}): PlanConfig | null => {
    const plan = getPlan(subscription);

    if (!plan || !subscription) {
        return null;
    }

    if (plan.Name === PLANS.MAIL) {
        return getMailPlusConfig({ plan, subscription, user });
    }

    if (plan.Name === PLANS.BUNDLE) {
        return getBundleConfig({ app, plan, subscription, user });
    }

    if (plan.Name === PLANS.FAMILY) {
        return getFamilyConfig({ plan, subscription, user });
    }

    if (plan.Name === PLANS.DUO) {
        return getDuoConfig({ app, plan, subscription, user });
    }

    if (plan.Name === PLANS.VISIONARY) {
        return getVisionaryConfig({ app, plan, subscription, user });
    }

    if (plan.Name === PLANS.DRIVE) {
        return getDrivePlusConfig({ plan, subscription, user });
    }

    if (plan.Name === PLANS.MAIL_PRO) {
        return getMailEssentialConfig({ plan, subscription, user });
    }

    if (plan.Name === PLANS.MAIL_BUSINESS) {
        return getMailBusinessConfig({ app, plan, subscription, user });
    }

    if (plan.Name === PLANS.BUNDLE_PRO_2024 || plan.Name === PLANS.BUNDLE_PRO) {
        return getBundleProConfig({ app, plan, subscription, user });
    }

    return null;
};
